.ds-push-range {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 2.5rem;
  margin: 0;
  background: transparent;
  cursor: pointer;
}
.ds-push-range::-webkit-slider-runnable-track {
  height: 2px;
  background: linear-gradient(to right, var(--amber, #ffb454) 0 var(--fill, 0%), rgba(242, 245, 255, 0.55) var(--fill, 0%) 100%);
  border-radius: 1px;
}
.ds-push-range::-moz-range-track { height: 2px; background: rgba(242, 245, 255, 0.55); border-radius: 1px; }
.ds-push-range::-moz-range-progress { height: 2px; background: var(--amber, #ffb454); }
.ds-push-range::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 1.75rem; height: 1.75rem;
  margin-top: calc(-0.875rem + 1px);
  background: var(--amber, #ffb454);
  border: 2px solid var(--ink, #0b1340);
  border-radius: var(--radius, 2px);
  box-shadow: 0 4px 14px -6px rgba(2, 8, 40, 0.9);
  transition: transform 140ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.ds-push-range::-moz-range-thumb {
  width: 1.75rem; height: 1.75rem;
  background: var(--amber, #ffb454);
  border: 2px solid var(--ink, #0b1340);
  border-radius: var(--radius, 2px);
  box-shadow: 0 4px 14px -6px rgba(2, 8, 40, 0.9);
}
.ds-push-range:hover::-webkit-slider-thumb, .ds-push-range:active::-webkit-slider-thumb { transform: scale(1.08); }
.ds-push-range:focus-visible { outline: none; }
.ds-push-range:focus-visible::-webkit-slider-thumb { outline: 3px solid var(--amber, #ffb454); outline-offset: 3px; }
.ds-push-range:focus-visible::-moz-range-thumb { outline: 3px solid var(--amber, #ffb454); outline-offset: 3px; }
@media(prefers-reduced-motion:reduce){.ds-preview *{transition-duration:0.01ms!important;animation-duration:0.01ms!important}}

.ds-preview {font-family:var(--text, "Archivo", "Helvetica Neue", Arial, sans-serif);font-size:1.0625rem;line-height:1.55;color:var(--ink, #0b1340);background:var(--board, #f4f6fb);padding:1.5rem}.ds-preview.ds-panel {background:var(--panel, #15309a);color:var(--line, #f2f5ff)} .ds-preview :focus-visible {outline:3px solid var(--panel, #15309a);outline-offset:3px;border-radius:var(--radius, 2px)} .ds-panel :focus-visible {outline-color:var(--amber, #ffb454)} .ds-faq details { border-bottom: 1px solid var(--ink-hair, rgba(11, 19, 64, 0.18)); }
.ds-faq summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  padding: 1.35rem 0;
  font-weight: 600;
  font-size: 1.2rem;
  line-height: 1.3;
  cursor: pointer;
  list-style: none;
}
.ds-faq summary::-webkit-details-marker { display: none; }
.ds-faq summary:hover { color: var(--panel, #15309a); }
.ds-faq .ds-toggle { width: 1.25rem; height: 1.25rem; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; }
.ds-faq .ds-toggle .ds-v { transform-origin: 50% 50%; transition: transform 220ms cubic-bezier(0.2, 0.8, 0.2, 1), opacity 160ms; }
.ds-faq details[open] .ds-toggle .ds-v { transform: rotate(90deg); opacity: 0; }
.ds-faq .ds-answer { padding: 0 0 1.5rem; max-width: 62ch; }
.ds-faq .ds-answer p { font-size: 1.05rem; line-height: 1.6; }
.ds-faq .ds-answer a { color: var(--panel, #15309a); font-weight: 500; }
.ds-faq summary em { font-style: italic; }.ds-answer p{margin:0}
